//! 🎟️ Original font-work authority reaches physical paged reservations and committed retained payload writes.
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use semio_framework_value_persistent::list::PagedList;
#[derive(Clone,Copy,Default)]
struct Hold{owner:usize,length:usize,bytes:usize,active:bool}
pub struct FontWorkLedger{grant:RetainedCloneGrant,actual:RetainedCloneProgress,pending:Option<RetirementDemand>,holds:[Hold;64],held:usize,nesting:usize,semantic_items:usize}
impl FontWorkLedger{
 pub fn new(grant:RetainedCloneGrant)->Self{Self{grant,actual:Default::default(),pending:None,holds:[Hold::default();64],held:0,nesting:0,semantic_items:0}}
 pub fn blocked(&self)->bool{self.pending.is_some()}
 pub fn enter(&mut self)->Option<bool>{let depth=self.nesting+1;if self.remaining().maximum_items==0||self.grant.maximum_depth<depth{self.pending=Some(RetirementDemand{depth,..Default::default()});return None;}let root=self.nesting==0;self.nesting+=1;Some(root)}
 pub fn exit(&mut self){self.nesting-=1;}
 pub fn can_step(&mut self)->bool{let depth=self.nesting.max(1);if self.remaining().maximum_items==0||self.grant.maximum_depth<depth{self.pending=Some(RetirementDemand{depth,..Default::default()});return false;}if self.nesting==0{self.note_source(true);}true}
 pub fn note_source(&mut self,root:bool){if root{self.semantic_items+=1;self.actual.copied_items=self.actual.copied_items.max(self.semantic_items);}}
 pub fn copy_bytes(&mut self,bytes:usize)->bool{let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_copy_bytes<bytes||remaining.maximum_depth<self.nesting+1{self.pending=Some(RetirementDemand{copy_bytes:self.held+bytes,depth:self.nesting+1,..Default::default()});return false;}self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=bytes;true}
 pub fn child_grant(&self)->RetainedCloneGrant{let grant=self.remaining();RetainedCloneGrant{maximum_depth:grant.maximum_depth.saturating_sub(self.nesting),..grant}}
 pub fn consume_child(&mut self,used:RetainedCloneProgress)->Result<(),&'static str>{let remaining=self.child_grant();self.actual.copied_items=self.actual.copied_items.max(used.copied_items);self.actual.copied_bytes=self.actual.copied_bytes.checked_add(used.copied_bytes).ok_or("font child copy overflow")?;self.actual.retained_capacity_bytes=self.actual.retained_capacity_bytes.checked_add(used.retained_capacity_bytes).ok_or("font child capacity overflow")?;self.actual.released_bytes=self.actual.released_bytes.checked_add(used.released_bytes).ok_or("font child release overflow")?;if used.copied_items>remaining.maximum_items||used.copied_bytes>remaining.maximum_copy_bytes||used.retained_capacity_bytes>remaining.maximum_capacity_bytes||used.released_bytes>remaining.maximum_release_bytes{return Err("font child exceeded original authority");}Ok(())}
 pub fn require_child(&mut self,demand:RetirementDemand)->Result<(),&'static str>{self.pending=Some(RetirementDemand{copy_bytes:demand.copy_bytes.checked_add(self.held).ok_or("font child demand overflow")?,depth:demand.depth.checked_add(self.nesting).ok_or("font child depth overflow")?,..demand});Ok(())}
 pub fn receipt(&self)->RetainedCloneProgress{self.actual}
 pub fn remaining(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.grant.maximum_items.saturating_sub(self.semantic_items),maximum_copy_bytes:self.grant.maximum_copy_bytes.saturating_sub(self.actual.copied_bytes).saturating_sub(self.held),maximum_capacity_bytes:self.grant.maximum_capacity_bytes.saturating_sub(self.actual.retained_capacity_bytes),maximum_release_bytes:self.grant.maximum_release_bytes.saturating_sub(self.actual.released_bytes),maximum_depth:self.grant.maximum_depth}}
 pub fn next_demand(&self)->RetirementDemand{self.pending.unwrap_or(RetirementDemand{depth:1,..Default::default()})}
 pub fn slot_demand<T>(values:&PagedList<T,{usize::MAX}>)->Result<RetirementDemand,&'static str>{if values.has_reserved_slot(){return Ok(RetirementDemand{copy_bytes:std::mem::size_of::<T>(),depth:1,..Default::default()});}Ok(RetirementDemand{copy_bytes:values.next_reserve_copy_byte_demand().map_err(|_|"font slot copy demand")?,capacity_bytes:values.next_allocation_bytes().map_err(|_|"font slot capacity demand")?,depth:values.next_reserve_depth_demand().map_err(|_|"font slot depth demand")?,release_bytes:0})}
 pub fn slot<T>(&mut self,values:&mut PagedList<T,{usize::MAX}>)->Result<bool,&'static str>{let owner=values as*const PagedList<T,{usize::MAX}>as usize;let length=values.len();if self.holds.iter().any(|hold|hold.active&&hold.owner==owner&&hold.length==length){return Ok(true);}let mut demand=Self::slot_demand(values)?;demand.depth+=self.nesting;let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_copy_bytes<demand.copy_bytes||remaining.maximum_capacity_bytes<demand.capacity_bytes||remaining.maximum_depth<demand.depth{self.pending=Some(RetirementDemand{copy_bytes:demand.copy_bytes+self.held,..demand});return Ok(false);}if demand.capacity_bytes>0{let result=values.reserve_one_funded(RetainedCloneGrant{maximum_depth:remaining.maximum_depth-self.nesting,..remaining});match result{Ok(p)=>{self.actual.copied_items=self.actual.copied_items.max(p.copied_items);self.actual.copied_bytes+=p.copied_bytes;self.actual.retained_capacity_bytes+=p.retained_capacity_bytes;self.actual.released_bytes+=p.released_bytes;let mut next=Self::slot_demand(values)?;next.copy_bytes+=self.held;next.depth+=self.nesting;self.pending=Some(next);return Ok(false);},Err(error)=>{self.actual.retained_capacity_bytes+=error.allocated_bytes;return Err("font physical page reservation failed");}}}let hold=self.holds.iter_mut().find(|hold|!hold.active).ok_or("font work hold count")?;*hold=Hold{owner,length,bytes:std::mem::size_of::<T>(),active:true};self.held+=hold.bytes;Ok(true)}
 pub fn contiguous<T>(&mut self,values:&mut Vec<T>,target:usize)->Result<bool,&'static str>{if values.capacity()>=target{return Ok(true);}if values.capacity()!=0||!values.is_empty(){return Err("font contiguous owner replacement refused");}let bytes=target.checked_mul(std::mem::size_of::<T>()).ok_or("font contiguous capacity overflow")?;let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_capacity_bytes<bytes||remaining.maximum_depth<self.nesting+1{self.pending=Some(RetirementDemand{copy_bytes:self.held,capacity_bytes:bytes,release_bytes:0,depth:self.nesting+1});return Ok(false);}values.try_reserve_exact(target).map_err(|_|"font contiguous admission failed")?;let actual=values.capacity()*std::mem::size_of::<T>();self.actual.retained_capacity_bytes+=actual;self.actual.copied_items=self.actual.copied_items.max(1);self.pending=Some(RetirementDemand{copy_bytes:self.held+std::mem::size_of::<T>(),depth:self.nesting+1,..Default::default()});if actual>remaining.maximum_capacity_bytes{return Err("font contiguous allocation exceeded original authority");}Ok(false)}
 pub fn vec_slot<T>(&mut self,values:&mut Vec<T>)->Result<bool,&'static str>{if values.len()==values.capacity(){return Err("font contiguous slot was not admitted");}let owner=values as*const Vec<T>as usize;let length=values.len();if self.holds.iter().any(|hold|hold.active&&hold.owner==owner&&hold.length==length){return Ok(true);}let bytes=std::mem::size_of::<T>();let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_copy_bytes<bytes||remaining.maximum_depth<1{self.pending=Some(RetirementDemand{copy_bytes:self.held+bytes,depth:self.nesting+1,..Default::default()});return Ok(false);}let hold=self.holds.iter_mut().find(|hold|!hold.active).ok_or("font work hold count")?;*hold=Hold{owner,length,bytes,active:true};self.held+=bytes;Ok(true)}
 pub fn vec_push<T>(&mut self,values:&mut Vec<T>,value:T)->Result<(),(&'static str,T)>{let owner=values as*const Vec<T>as usize;let Some(hold)=self.holds.iter_mut().find(|hold|hold.active&&hold.owner==owner&&hold.length==values.len())else{return Err(("font contiguous copy authority missing",value));};if values.len()==values.capacity(){return Err(("font contiguous slot missing",value));}values.push(value);hold.active=false;self.held-=hold.bytes;self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=hold.bytes;Ok(())}
 pub fn push<T>(&mut self,values:&mut PagedList<T,{usize::MAX}>,value:T)->Result<(),(&'static str,T)>{let owner=values as*const PagedList<T,{usize::MAX}>as usize;let Some(hold)=self.holds.iter_mut().find(|hold|hold.active&&hold.owner==owner&&hold.length==values.len())else{return Err(("font copy authority missing",value));};let bytes=hold.bytes;match values.push_reserved(value){Ok(())=>{hold.active=false;self.held-=bytes;self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=bytes;Ok(())},Err(value)=>Err(("font original reservation lost",value))}}
}
#[cfg(test)]#[path="🧪️tests/🦀️.rs"]mod tests;
